  campeche: { name: 'Praia do Campeche', region: 'Florianópolis, Brazil', blurb: 'Long, exposed east-facing beach — the island’s wave when everywhere else is too small.', lat: -27.6720, lon: -48.4750, offshoreDeg: 280 },
  barradalagoa: { name: 'Barra da Lagoa', region: 'Florianópolis, Brazil', blurb: 'Sheltered corner beside the canal, a forgiving option when the swell is up everywhere else.', lat: -27.5760, lon: -48.4270, offshoreDeg: 265 },
  santinho: { name: 'Praia do Santinho', region: 'Florianópolis, Brazil', blurb: 'North-east corner of the island with a rocky point at each end and consistent banks between.', lat: -27.4600, lon: -48.3880, offshoreDeg: 255 },
