  praiadofuturo: { name: 'Praia do Futuro', region: 'Fortaleza, Brazil', blurb: 'Windy, warm, and relentlessly consistent — short-period swell almost every day of the year.', lat: -3.7530, lon: -38.4560, offshoreDeg: 235 },
