  bagasbas: { name: 'Bagasbas', region: 'Camarines Norte, Philippines', blurb: 'Wide, gently sloping beach on the Pacific side — a good place to learn in warm water.', lat: 14.1350, lon: 122.9670, offshoreDeg: 220 },
