  shipwrecksnl: { name: 'Shipwrecks (Lembongan)', region: 'Nusa Lembongan, Indonesia', blurb: 'Long right over shallow reef off Lembongan’s northern tip, best with a bit of size.', lat: -8.6730, lon: 115.4590, offshoreDeg: 220 },
