  sawarna: { name: 'Sawarna', region: 'Banten, Indonesia', blurb: 'Remote stretch of west Java coast, fully exposed to Indian Ocean swell and rarely crowded.', lat: -6.9880, lon: 106.3160, offshoreDeg: 20 },
